-- Generated by src/pipeline.py; use the pipeline to load data.
CREATE TABLE dim_date(date TEXT PRIMARY KEY, year INTEGER NOT NULL, quarter INTEGER NOT NULL,
 month_number INTEGER NOT NULL, month TEXT NOT NULL, month_name TEXT NOT NULL,
 weekday TEXT NOT NULL, weekday_number INTEGER NOT NULL, is_weekend INTEGER NOT NULL);

CREATE TABLE dim_route(route_key INTEGER PRIMARY KEY, route TEXT UNIQUE NOT NULL,
 source_station TEXT NOT NULL, destination_station TEXT NOT NULL,
 distance_km INTEGER NOT NULL, railway_zone TEXT NOT NULL);

CREATE TABLE dim_train(train_number TEXT PRIMARY KEY, train_type TEXT NOT NULL, train_capacity INTEGER NOT NULL);

CREATE TABLE fact_booking (booking_id TEXT PRIMARY KEY,user_id TEXT NOT NULL,booking_date TEXT NOT NULL,booking_time TEXT NOT NULL,travel_date TEXT NOT NULL,train_number TEXT NOT NULL,train_name TEXT NOT NULL,train_type TEXT NOT NULL,railway_zone TEXT NOT NULL,source_station TEXT NOT NULL,destination_station TEXT NOT NULL,route TEXT NOT NULL,distance_km INTEGER NOT NULL,travel_class TEXT NOT NULL,booking_type TEXT NOT NULL,booking_channel TEXT NOT NULL,partner_platform TEXT NOT NULL,passenger_count INTEGER NOT NULL,base_fare_inr INTEGER NOT NULL,surge_tatkal_charges_inr INTEGER NOT NULL,catering_charges_inr INTEGER NOT NULL,taxes_and_convenience_inr INTEGER NOT NULL,booking_value_inr INTEGER NOT NULL,payment_method TEXT NOT NULL,booking_status TEXT NOT NULL,train_capacity INTEGER NOT NULL,occupancy_percentage REAL NOT NULL CHECK (occupancy_percentage BETWEEN 0 AND 100),on_time_delay_mins INTEGER NOT NULL,source_row_number INTEGER NOT NULL,booking_month TEXT NOT NULL,booking_weekday TEXT NOT NULL,booking_hour INTEGER NOT NULL,lead_time_days INTEGER NOT NULL,flag_invalid_chronology INTEGER NOT NULL,valid_lead_time_days INTEGER,charge_components_inr INTEGER NOT NULL,charge_difference_inr INTEGER NOT NULL,flag_charge_mismatch INTEGER NOT NULL,flag_train_metadata_conflict INTEGER NOT NULL,flag_train_date_occupancy_conflict INTEGER NOT NULL,flag_train_date_delay_conflict INTEGER NOT NULL,route_key INTEGER NOT NULL,FOREIGN KEY(booking_date) REFERENCES dim_date(date),FOREIGN KEY(travel_date) REFERENCES dim_date(date),FOREIGN KEY(train_number) REFERENCES dim_train(train_number),FOREIGN KEY(route_key) REFERENCES dim_route(route_key),CHECK(passenger_count > 0),CHECK(booking_value_inr >= 0),CHECK(charge_difference_inr = 0));

CREATE INDEX idx_booking_channel_status ON fact_booking(booking_channel,booking_status);

CREATE INDEX idx_booking_date ON fact_booking(booking_date);

CREATE INDEX idx_booking_route ON fact_booking(route_key);

CREATE INDEX idx_booking_train_date ON fact_booking(train_number,travel_date);

CREATE VIEW v_channels AS SELECT booking_channel, COUNT(*) row_count, SUM(booking_value_inr) booking_value_inr,
 SUM(passenger_count) passengers FROM fact_booking GROUP BY booking_channel;

CREATE VIEW v_monthly AS SELECT booking_month, COUNT(*) row_count, SUM(booking_value_inr) booking_value_inr,
 SUM(passenger_count) passengers, AVG(booking_value_inr) avg_booking_value_inr,
 SUM(flag_invalid_chronology) invalid_chronology_count FROM fact_booking GROUP BY booking_month;

CREATE VIEW v_routes AS SELECT route, COUNT(*) row_count, SUM(booking_value_inr) booking_value_inr,
 SUM(passenger_count) passengers FROM fact_booking GROUP BY route;

CREATE VIEW v_status AS SELECT booking_status, COUNT(*) row_count, SUM(booking_value_inr) booking_value_inr,
 SUM(passenger_count) passengers FROM fact_booking GROUP BY booking_status;
